            # find nonzero markers in each cell and select fill color by marker
            markers = [grid[i][j] for i in range(a+1,b) for j in range(c+1,d) if grid[i][j] not in (0,8)]
            if not markers:
                continue
            color = markers[0]
            if color == 2:
                fill = 2
            elif color == 3:
                fill = 6
            else:
                continue
            for i in range(a+1,b):
