    for i in range(h):
        for j in range(w):
            if grid[i][j] == 8: out[i][j] = 8
    # Demo: 3 markers indicate a horizontal strip: each cell across that row-block is 3,
    # while the marked cell is 6. Color-2 markers fill their entire cell with 2.
    for a,b in zip(rb, rb[1:]):
        markcells = []
        for c,d in zip(cb, cb[1:]):
            marks=[grid[i][j] for i in range(a+1,b) for j in range(c+1,d) if grid[i][j] not in (0,8)]
            if marks: markcells.append((c,d,marks[0]))
        if any(col == 3 for _,_,col in markcells):
            for i in range(a+1,b):
                for c,d in zip(cb, cb[1:]):
                    for j in range(c+1,d): out[i][j] = 3
            for c,d,col in markcells:
                if col == 3:
                    for i in range(a+1,b):
                        for j in range(c+1,d): out[i][j] = 6
    return out
